// Volume landing page content tests (#1080).
//
// Generated by hsg:volume-landing-content()/hsg:volume-ways-to-explore() in
// modules/templates/hsg.xqm: title, cover image, editor/general editor,
// publisher info, the full table of contents (front matter, the
// compilation with nested chapters and document-number ranges, back
// matter), and the "Ways to Explore" sidebar (search-within-volume, ebook
// downloads, GPO bookstore link). Reference parity with hsg-shell.
//
// Tags is out of scope here -- covered by a separate PR (#19).

const VOLUME = "historicaldocuments/frus1981-88v05";

describe("volume landing page", () => {
    beforeEach(() => cy.visit(VOLUME));

    it("shows the cover image", () => {
        cy.get("main h1")
            .next("img.hsg-frus__cover")
            .should("have.attr", "src", "https://static.history.state.gov/frus/frus1981-88v05/covers/frus1981-88v05.jpg")
            .and("have.attr", "alt")
            .and("contain", "Book Cover of");
    });

    it("shows Editor and General Editor", () => {
        cy.get(".hsg-frus__editor-label").eq(0).should("have.text", "Editor:");
        cy.get(".hsg-list-editors").eq(0).should("contain.text", "Elizabeth C. Charles");
        cy.get(".hsg-frus__editor-label").eq(1).should("have.text", "General Editor:");
        cy.get(".hsg-list-editors").eq(1).should("contain.text", "Kathleen B. Rasmussen");
    });

    it("shows publisher, place, and publication year", () => {
        cy.get(".hsg-frus__published").should("contain.text", "United States Government Publishing Office")
            .and("contain.text", "Washington")
            .and("contain.text", "2020");
    });

    it("lists front matter, the compilation with nested chapters and document ranges, and back matter", () => {
        cy.get("ul.hsg-frus__toc > li > a").then(($as) => {
            const texts = [...$as].map((el) => el.textContent.trim());
            expect(texts).to.include("Press Release");
            expect(texts).to.include("About the Series");
            expect(texts).to.include("Preface");
            expect(texts).to.include("Sources");
            expect(texts).to.include("Abbreviations and Terms");
            expect(texts).to.include("Persons");
            expect(texts).to.include("Index");
        });
        cy.get("ul.hsg-frus__toc").should("contain.text", "Documents 1–309");
        cy.get("ul.hsg-frus__toc").should("contain.text", "Documents A–C");
        cy.get("ul.hsg-frus__toc ul li").should("have.length.at.least", 6);
        cy.get("ul.hsg-frus__toc ul li a[href$='/ch1']")
            .parent()
            .should("contain.text", "Documents 1–50");
    });

    it("has a 'Ways to Explore' panel with search, ebook downloads, and the GPO link", () => {
        cy.get(".hsg-frus__ways-to-explore").within(() => {
            cy.get("h2").should("contain.text", "Ways to Explore");
            cy.get("form[action$='/search']").within(() => {
                cy.get("input[name='q']").should("exist");
                cy.get("input[name='volume-id']").should("have.value", "frus1981-88v05");
            });
            cy.get("a.hsg-link-button").should("have.length", 3);
            cy.get("a.hsg-link-button").eq(0).should("contain.text", "EPUB").and("have.attr", "href").and("match", /\.epub$/);
            cy.get("a.hsg-link-button").eq(1).should("contain.text", "Mobi").and("have.attr", "href").and("match", /\.mobi$/);
            cy.get("a.hsg-link-button").eq(2).should("contain.text", "PDF").and("have.attr", "href").and("match", /\.pdf$/);
            cy.get("a[href*='bookstore.gpo.gov']").should("exist");
        });
    });
});

// Regression: a microfiche supplement's notesStmt carries one relatedItem per
// associated file (frus1958-60v05mSupp has 562 type="pdf" entries, one per
// document) alongside the volume's own downloads. Selecting ebook links by
// @type alone matched all 562 and the page died with an XPTY0004 cardinality
// error; the volume's own items are identified by @corresp = "#<volume-id>",
// the same gate hsg-shell's fh:exists-pdf and friends use.
describe("volume landing page for a microfiche supplement", () => {
    const SUPPLEMENT = "historicaldocuments/frus1958-60v05mSupp";

    beforeEach(() => cy.visit(SUPPLEMENT));

    it("renders instead of erroring on the per-document relatedItems", () => {
        cy.get("main h1").should("contain.text", "Microfiche Supplement");
        cy.get(".hsg-frus__ways-to-explore").should("exist");
    });

    it("links only the volume-level ebook downloads, not the per-document PDFs", () => {
        cy.get(".hsg-frus__ways-to-explore").within(() => {
            cy.get("a.hsg-link-button").should("have.length", 3);
            cy.get("a.hsg-link-button[href$='frus1958-60v05mSupp.epub']").should("exist");
            cy.get("a.hsg-link-button[href$='frus1958-60v05mSupp.mobi']").should("exist");
            // The volume PDF, not one of the 562 per-document ones.
            cy.get("a.hsg-link-button[href$='frus1958-60v05mSupp.pdf']").should("exist");
        });
    });

    it("still shows the cover image", () => {
        cy.get("img.hsg-frus__cover")
            .should("have.attr", "src", "https://static.history.state.gov/frus/frus1958-60v05mSupp/covers/frus1958-60v05mSupp.jpg");
    });
});
